 72	  private call<T>(method: string, params?: unknown): Promise<T> {
 73	    const id = `${++this.requestId}_${Date.now()}`;
 74	
 75	    return new Promise((resolve, reject) => {
 76	      const timeout = setTimeout(() => {
 77	        this.pending.delete(id);
 78	        reject(new Error(`Bridge ${method} timed out`));
 79	      }, 600000);
 80	
 81	      this.pending.set(id, { resolve: resolve as (v: unknown) => void, reject, timeout });
 82	      this.vscode.postMessage({ id, method, params, webviewId: this.webviewId });
 83	    });
 84	  }
