 12	function resolveAgentFile(
 13	  activeTab: 'think' | 'do',
 14	  workspaceRoot: string | null,
 15	  extensionRoot: string,
 16	): string | undefined {
 17	  const agentName = activeTab === 'think' ? 'think.yaml' : 'do.yaml';
 18	
 19	  // 1. Workspace-local override
 20	  if (workspaceRoot) {
 21	    const localPath = path.join(workspaceRoot, '.consilium', 'agents', agentName);
 22	    if (fs.existsSync(localPath)) {
 23	      return localPath;
 24	    }
 25	  }
 26	
 27	  // 2. Built-in profile template
 28	  const profile = VSCodeSettings.agentProfile;
 29	  if (profile && extensionRoot) {
 30	    const templatePath = path.join(extensionRoot, 'resources', 'agent-profiles', profile, agentName);
 31	    if (fs.existsSync(templatePath)) {
 32	      return templatePath;
 33	    }
 34	  }
 35	
 36	  // 3. Fallback to CLI default (no --agent-file)
 37	  return undefined;
 38	}
